* {
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font-display);
  overflow: hidden;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

canvas {
  display: block;
  touch-action: none;
}

button {
  font-family: inherit;
  cursor: pointer;
}

::selection {
  background: var(--magenta);
  color: #08090f;
}
