% 0%, #101935 0%, #070a14 45%, #04050a 100%);\n}\n\n.app__canvas {\n  position: absolute;\n  inset: 0;\n}\n\n.scanlines {\n  position: absolute;\n  inset: 0;\n  pointer-events: none;\n  z-index: 40;\n  opacity: 0.35;\n  background: repeating-linear-gradient(\n    to bottom,\n    rgba(255, 255, 255, 0.035) 0px,\n    rgba(255, 255, 255, 0.035) 1px,\n    transparent 1px,\n    transparent 3px\n  );\n  mix-blend-mode: overlay;\n}\n\n.vignette {\n  position: absolute;\n  inset: 0;\n  pointer-events: none;\n  z-index: 39;\n  background: radial-gradient(120% 100% at 50% 50%, transparent 52%, rgba(0, 0, 0, 0.72) 100%);\n}\n\n/* ------------------------------------------------------------------ screens */\n\n.screen {\n  position: absolute;\n  inset: 0;\n  z-index: 30;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  padding: 4vh 5vw;\n  overflow-y: auto;\n}\n\n.screen--menu {\n  background:\n    radial-gradient(80% 60% at 18% 12%, rgba(255, 46, 136, 0.16), transparent 60%),\n    radial-gradient(70% 60% at 84% 82%, rgba(0, 229, 255, 0.16), transparent 60%),\n    linear-gradient(180deg, rgba(4, 5, 10, 0.86), rgba(4, 5, 10, 0.95));\n  backdrop-filter: blur(3px);\n}\n\n/* --------------------------------------------------------------- main menu */\n\n.menu {\n  width: min(1080px, 100%);\n  display: grid;\n  grid-template-columns: 1.25fr 0.75fr;\n  gap: clamp(20px, 4vw, 56px);\n  align-items: center;\n  animation: fade-up 0.5s ease both;\n}\n\n@media (max-width: 860px) {\n  .menu {\n    grid-template-columns: 1fr;\n    gap: 28px;\n  }\n}\n\n.menu__eyebrow {\n  font-family: var(--font-mono);\n  font-size: 12px;\n  letter-spacing: 0.42em;\n  text-transform: uppercase;\n  color: var(--cyan);\n  margin: 0 0 10px;\n  opacity: 0.85;\n}\n\n.menu__title {\n  margin: 0;\n  font-size: clamp(56px, 11vw, 132px);\n  line-height: 0.86;\n  font-weight: 800;\n  letter-spacing: -0.02em;\n  text-transform: uppercase;\n  color: #f2f7ff;\n  text-sha